#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_inorder_display_non_empty_tree(void) {
    // Setup: Build a non-empty binary tree to trigger the path (curr != NULL)
    int values[] = {5, 3, 7, 2, 4, 6, 8};
    int size = sizeof(values) / sizeof(values[0]);
    node* root = NULL;
    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    // Capture stdout to verify the function prints something
    FILE* original_stdout = stdout;
    FILE* temp_file = tmpfile();
    TEST_ASSERT_NOT_NULL(temp_file);
    stdout = temp_file;

    // Test: call inorder_display on non-empty tree
    inorder_display(root);
    fflush(stdout);

    // Stop capture and get output
    stdout = original_stdout;
    fseek(temp_file, 0, SEEK_END);
    long file_size = ftell(temp_file);
    fseek(temp_file, 0, SEEK_SET);
    char* output = malloc(file_size + 1);
    TEST_ASSERT_NOT_NULL(output);
    fread(output, 1, file_size, temp_file);
    output[file_size] = '\0';
    fclose(temp_file);

    // Assertions: output should not be empty (since tree is non-empty)
    TEST_ASSERT_TRUE(strlen(output) > 0);

    // Cleanup
    free(output);
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_inorder_display_non_empty_tree);
    return UNITY_END();
}

